#!/usr/bin/env python3
"""Validator for auto-generated law regression tests (T-20).

Scans framework/sps2/tests/test_law_regress_*.py — the negative tests emitted
by gen_law_test.py — and refuses any generated test that has not been through
the human gate: each file must carry BOTH header lines

    # AUTO-GENERATED by gen_law_test.py (T-20)
    # reviewed by: <reviewer name / date>

A missing marker, or a reviewed-by value that is empty or a placeholder
(`<user/date>`, TBD, TODO, pending, ...), is a violation. Generation proposes;
only an explicit `--approved-by` write (plus this review field) makes a
generated test part of the battery — nothing auto-lands.

Format and exit convention mirror check_laws.py: one violation per line on
stderr (`CHECK_ID: target_file: detail`), a `== ... CHECK: N violation(s) ==`
summary, exit 0 when all hold, exit 1 otherwise. Stdlib-only, project-local.
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[3]
TESTS_DIR = REPO / "framework" / "sps2" / "tests"
AUTO_MARKER = "AUTO-GENERATED by gen_law_test.py (T-20)"
REVIEWED_PREFIX = "# reviewed by:"
CHECK_ID = "GENERATED_TEST_UNREVIEWED"

# Placeholder reviewed-by values: angle-bracket templates or empty filler.
PLACEHOLDER = re.compile(
    r"^(<[^>]*>|\?+|tbd\b.*|todo\b.*|pending\b.*|n/?a$|placeholder$|your name$|user/date$)",
    re.IGNORECASE,
)


def reviewed_by_value(text: str) -> tuple[bool, str | None]:
    """Return (found, value) for the reviewed-by header.

    Tolerates the value on the marker line itself (gen_law_test.py emits
    `# AUTO-GENERATED ... — reviewed by: <user/date>`) or on its own line.
    found=True when any 'reviewed by:' line exists; value is the first
    non-empty candidate on such a line (same line only — never spans lines).
    """
    found = False
    value: str | None = None
    for line in text.splitlines():
        if "reviewed by:" in line:
            found = True
            candidate = line.split("reviewed by:", 1)[1].strip()
            if candidate and value is None:
                value = candidate
    return found, value


def check_file(path: Path) -> str | None:
    """Return a violation message for one generated test, or None if it passes."""
    text = path.read_text(encoding="utf-8", errors="replace")
    if AUTO_MARKER not in text:
        return (f"{CHECK_ID}: {path}: missing auto-generation header "
                f"'# {AUTO_MARKER}' — not a valid generated test")
    found, value = reviewed_by_value(text)
    if not found:
        return (f"{CHECK_ID}: {path}: missing 'reviewed by:' header — "
                f"generated tests are not valid until a human reviews them")
    if not value or PLACEHOLDER.match(value):
        shown = value if value else "<empty>"
        return (f"{CHECK_ID}: {path}: reviewed-by value '{shown}' is empty or "
                f"a placeholder — fill in the reviewer name/date")
    return None


def check_dir(tests_dir: Path | None = None) -> list[str]:
    """Check every test_law_regress_*.py in tests_dir; return violation lines."""
    tests_dir = tests_dir or TESTS_DIR
    out: list[str] = []
    if not tests_dir.is_dir():
        return out
    for path in sorted(tests_dir.glob("test_law_regress_*.py")):
        msg = check_file(path)
        if msg:
            out.append(msg)
    return out


def main(argv: list[str] | None = None) -> int:
    args = sys.argv[1:] if argv is None else argv
    tests_dir = Path(args[0]) if args else TESTS_DIR
    violations = check_dir(tests_dir)
    if not violations:
        if not any(tests_dir.glob("test_law_regress_*.py")):
            print(f"note: no generated tests (test_law_regress_*.py) in "
                  f"{tests_dir} — nothing to validate")
        print("== GENERATED-TEST CHECK: all generated tests reviewed ==")
        return 0
    for msg in violations:
        print(msg, file=sys.stderr)
    print(f"\n== GENERATED-TEST CHECK: {len(violations)} violation(s) ==",
          file=sys.stderr)
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
